package pe.edu.cacaoselva.desktop.view;
import javafx.beans.property.SimpleStringProperty; import javafx.geometry.Insets; import javafx.scene.control.*; import javafx.scene.layout.*; import pe.edu.cacaoselva.application.port.LoteDto; import java.util.List;
public class LoteView extends BorderPane { private final Button consultarButton=new Button("Consultar"); private final Label estadoLabel=new Label("Listo"); private final TableView<LoteDto> table=new TableView<>(); public LoteView(){setPadding(new Insets(20)); Label title=new Label("CacaoSelva - Consulta de lotes"); title.setStyle("-fx-font-size:20px;-fx-font-weight:bold;"); TableColumn<LoteDto,String> id=new TableColumn<>("ID"); id.setCellValueFactory(d->new SimpleStringProperty(String.valueOf(d.getValue().id()))); TableColumn<LoteDto,String> socio=new TableColumn<>("Socio"); socio.setCellValueFactory(d->new SimpleStringProperty(d.getValue().socio())); TableColumn<LoteDto,String> peso=new TableColumn<>("Peso (kg)"); peso.setCellValueFactory(d->new SimpleStringProperty(d.getValue().pesoKg().toPlainString())); TableColumn<LoteDto,String> estado=new TableColumn<>("Estado"); estado.setCellValueFactory(d->new SimpleStringProperty(d.getValue().estado().name())); table.getColumns().addAll(id,socio,peso,estado); table.setColumnResizePolicy(TableView.CONSTRAINED_RESIZE_POLICY_ALL_COLUMNS); setTop(new VBox(12,title,new HBox(10,consultarButton,estadoLabel))); setCenter(table);} public Button getConsultarButton(){return consultarButton;} public void mostrarLotes(List<LoteDto> lotes){table.getItems().setAll(lotes);} public void mostrarEstado(String mensaje){estadoLabel.setText(mensaje);} }
